import sys
import csv

def main(path):
    students = {}
    r = csv.reader(open(path))
    header = next(r)
    for row in r:
        name = row[0]
        kind = row[1]
        score = float(row[2])
        if name not in students:
            students[name] = {"hw": [], "quiz": [], "exam": []}
        if kind == "hw":
            students[name]["hw"].append(score)
        elif kind == "quiz":
            students[name]["quiz"].append(score)
        elif kind == "exam":
            students[name]["exam"].append(score)
    for name in sorted(students.keys()):
        s = students[name]
        if len(s["hw"]) > 0:
            hw_avg = sum(s["hw"]) / len(s["hw"])
        else:
            hw_avg = 0.0
        if len(s["quiz"]) > 0:
            if len(s["quiz"]) > 1:
                drop = min(s["quiz"])
                quiz_avg = (sum(s["quiz"]) - drop) / (len(s["quiz"]) - 1)
            else:
                quiz_avg = s["quiz"][0]
        else:
            quiz_avg = 0.0
        if len(s["exam"]) > 0:
            exam_avg = sum(s["exam"]) / len(s["exam"])
        else:
            exam_avg = 0.0
        final = hw_avg * 0.3 + quiz_avg * 0.2 + exam_avg * 0.5
        if final >= 90:
            letter = "A"
        elif final >= 80:
            letter = "B"
        elif final >= 70:
            letter = "C"
        elif final >= 60:
            letter = "D"
        else:
            letter = "F"
        print("%s: hw=%.1f quiz=%.1f exam=%.1f final=%.1f %s" % (name, hw_avg, quiz_avg, exam_avg, final, letter))

if __name__ == "__main__":
    main(sys.argv[1])

Step 1, characterization: build a CSV fixture with students hitting every branch: a student with one quiz (no drop), several quizzes (lowest dropped), missing categories entirely, boundary finals landing exactly on 90/80/70/60 (engineer inputs so the weighted final is exactly on the boundary), and assert exact stdout via subprocess in tests/test_golden.py. Green before refactor. Step 2: extract pure functions average(xs), quiz_average_with_drop(xs), weighted_final(hw, quiz, exam), letter_grade(final), and grade_report(rows) -> list[str]; the file-reading and printing shrink to a thin main. Step 3: golden test still byte-identical; add unit tests including letter_grade boundaries at exactly 90/80/70/60 and 89.95 (which %.1f displays as 90.0 but grades as B; capture that trap in a test comment and assertion). pytest green throughout.

