result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/gradebook.py", "content": "import sys
import csv


def average(xs):
    if len(xs) > 0:
        return sum(xs) / len(xs)
    return 0.0


def quiz_average_with_drop(xs):
    if len(xs) > 0:
        if len(xs) > 1:
            drop = min(xs)
            return (sum(xs) - drop) / (len(xs) - 1)
        return xs[0]
    return 0.0


def weighted_final(hw_avg, quiz_avg, exam_avg):
    return hw_avg * 0.3 + quiz_avg * 0.2 + exam_avg * 0.5


def letter_grade(final):
    if final >= 90:
        return "A"
    elif final >= 80:
        return "B"
    elif final >= 70:
        return "C"
    elif final >= 60:
        return "D"
    else:
        return "F"


def grade_report(rows):
    students = {}
    for row in rows:
        name = row[0]
        kind = row[1]
        score = float(row[2])
        if name not in students:
            students[name] = {"hw": [], "quiz": [], "exam": []}
        if kind == "hw":
            students[name]["hw"].append(score)
        elif kind == "quiz":
            students[name]["quiz"].append(score)
        elif kind == "exam":
            students[name]["exam"].append(score)
    lines = []
    for name in sorted(students.keys()):
        s = students[name]
        hw_avg = average(s["hw"])
        quiz_avg = quiz_average_with_drop(s["quiz"])
        exam_avg = average(s["exam"])
        final = weighted_final(hw_avg, quiz_avg, exam_avg)
        letter = letter_grade(final)
        lines.append("%s: hw=%.1f quiz=%.1f exam=%.1f final=%.1f %s" % (name, hw_avg, quiz_avg, exam_avg, final, letter))
    return lines


def main(path):
    r = csv.reader(open(path))
    next(r)  # skip header
    for line in grade_report(r):
        print(line)


if __name__ == "__main__":
    main(sys.argv[1])
